starter:
def count_substring_occurrences(s, sub):
    # your code here
    pass

solution:
def count_substring_occurrences(s, sub):
    if sub == "":
        return 0
    count = 0
    i = 0
    while i <= len(s) - len(sub):
        if s[i:i + len(sub)] == sub:
            count += 1
            i += len(sub)
        else:
            i += 1
    return count

